import java.util.*;

public class V5 {
    static boolean isSpecial(char ch) {
        return ch == '(' || ch == ')' || ch == '_';
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        String s = sc.next();

        boolean inside = false;
        int insideLen = 0;
        int outsideLen = 0;
        int ans1 = 0, ans2 = 0;

        for (int i = 0; i < n; i++) {
            char ch = s.charAt(i);
            if (inside) {
                if (ch == '_') {
                    if (insideLen > 0) ans2++;
                    insideLen = 0;
                } else if (ch == ')') {
                    if (insideLen > 0) ans2++;
                    insideLen = 0;
                    inside = false;
                } else {
                    insideLen++;
                }
            } else {
                if (ch == '(') {
                    ans1 = Math.max(ans1, outsideLen);
                    outsideLen = 0;
                    inside = true;
                    insideLen = 0;
                } else if (isSpecial(ch)) {
                    ans1 = Math.max(ans1, outsideLen);
                    outsideLen = 0;
                } else {
                    outsideLen++;
                }
            }
        }
        ans1 = Math.max(ans1, outsideLen);
        System.out.println(ans1 + " " + ans2);
    }
}
